from pathlib import Path
import json,re,sys
ROOT=Path(__file__).resolve().parent/'edition001'
sources=json.loads((ROOT/'source.json').read_text());by={a['number']:a for a in sources};out={}
def paragraphs(text):return ''.join('<p>'+p.strip()+'</p>' for p in text.strip().split('\n\n'))
def base(n):return by[n].get('previous_draft',{}).get('proposed_xml') or by[n]['source_xml']
def clean(body):return re.sub(r'\s+align="[^"]*"','',body)
T="Les contrats conclus avant l'entrée en vigueur de la réforme du contrat unique restent régis par les dispositions qui leur étaient applicables ; leurs droits et créances acquis sont conservés. Aucune conversion en contrat unique ne remet l'ancienneté à zéro."
N="Pour les contrats uniques conclus à compter de l'entrée en vigueur de la réforme, "
C="Le contrat de travail reste à durée indéterminée. La fin d'une mission, d'une formation ou d'une aide ne le rompt pas automatiquement. Sa rupture relève des règles du contrat unique, notamment du préavis individuel de quinze jours calendaires et de l'indemnité ordinaire de l'article L. 1234-9 lorsqu'elle est due."
def put(n,body,reason,notes='',removed=None):
 a=by[n];row={k:a[k] for k in ('code_id','source_id','source_sha256','number')};row.update(proposed_xml=clean(body),reason=reason,review_notes=notes or "Coordination avec L1221-2, L1234-1, L1234-9, L1237-1 et la transition L1241-1. Source officielle et notes lues intégralement ; proposition de réforme, sans validation par un juriste.",status='rewrite_draft')
 if removed:row.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
 row['benefit_review']="Les droits, exonérations, majorations ou dispenses mentionnés dans cet article restent ouverts aux situations éligibles futures dans le contrat unique, selon leur objet propre. "+reason+" Les avantages et créances des contrats antérieurs sont conservés sans remise à zéro de l'ancienneté."
 out[n]=row

def transition(n,new,reason,notes='',removed=None):
 put(n,paragraphs(N+new)+paragraphs("Pour les contrats conclus avant cette entrée en vigueur, les règles suivantes demeurent applicables :")+clean(base(n))+paragraphs(T),reason,notes,removed)

def replace(n,old,new,reason,extra='',notes=''):
 body=base(n);assert body.count(old)==1,(n,old);body=body.replace(old,new)
 put(n,body+paragraphs(extra) if extra else body,reason,notes)

# Intérim : l'objet commercial de chaque mission demeure temporaire, l'emploi ne l'est plus.
put('L1251-1',paragraphs("Le travail temporaire consiste, pour une entreprise de travail temporaire, à mettre temporairement un salarié à la disposition d'un client utilisateur pour l'exécution d'une mission.\n\nChaque mission donne lieu :\n\n1° À un contrat de mise à disposition entre l'entreprise de travail temporaire et le client utilisateur, appelé entreprise utilisatrice ;\n\n2° Pour un salarié recruté à compter de l'entrée en vigueur de la réforme du contrat unique, à une lettre de mission établie dans le cadre du contrat unique à durée indéterminée qui le lie à l'entreprise de travail temporaire. Ce contrat est régi par les articles L. 1251-58-1 à L. 1251-58-6. La mission ne constitue pas un contrat de travail distinct et sa fin ne rompt pas le contrat unique.\n\nLes contrats de mission conclus avant cette entrée en vigueur restent soumis à leurs règles antérieures jusqu'à leur terme, sans nouveau renouvellement à durée déterminée après cette date ; toute relation de travail nouvelle relève du contrat unique. Les rémunérations, indemnités de mission et recours acquis sont conservés.\n\nLorsque l'utilisateur est une personne morale de droit public, le présent chapitre s'applique sous réserve de la section 6."),'Remplace le nouveau contrat de mission à terme par une lettre de mission dans un emploi unique à durée indéterminée, en conservant le régime des missions anciennes.')
put('L1251-2',paragraphs("Est entrepreneur de travail temporaire toute personne physique ou morale dont l'activité exclusive consiste à mettre temporairement des salariés à la disposition d'entreprises utilisatrices. Cette personne recrute et rémunère ces salariés selon une qualification convenue.\n\nLes recrutements effectués à compter de l'entrée en vigueur de la réforme du contrat unique prennent la forme du contrat unique à durée indéterminée, y compris lorsque l'affectation auprès d'un utilisateur est temporaire. Les garanties de rémunération et d'intermission prévues aux articles L. 1251-58-2 et L. 1251-58-3 s'appliquent."),'Rend explicite le recrutement à durée indéterminée par l’agence tout en conservant le caractère temporaire de la mise à disposition.')
season="Les emplois saisonniers dont les tâches sont appelées à se répéter chaque année selon une périodicité à peu près fixe, en fonction du rythme des saisons ou des modes de vie collectifs ; ainsi que les missions liées à une activité qui, par sa nature, est temporaire, dans les secteurs définis par décret ou par convention ou accord collectif étendu. Ces caractéristiques concernent l'affectation et ne permettent pas de fixer un terme au contrat unique"
replace('L1251-6',"Les emplois à caractère saisonnier définis au 3° de l'article L. 1242-2 ou les emplois pour lesquels il est d'usage constant de ne pas recourir au contrat de travail à durée indéterminée en raison de la nature de l'activité exercée et du caractère par nature temporaire de ces emplois. Dans ce dernier cas, les secteurs concernés sont définis par décret ou par convention ou accord collectif étendu",season,'Remplace le renvoi au CDD saisonnier supprimé par une définition objective des missions, sans terme automatique de l’emploi.',extra="Le présent article détermine les cas d'affectation temporaire auprès de l'utilisateur, sans déroger au contrat unique à durée indéterminée applicable aux nouveaux recrutements. Les anciens contrats de mission conservent leur régime de durée et leurs droits.")
replace('L1251-11',"Pour occuper un emploi à caractère saisonnier défini au 3° de l'article L. 1242-2, ou un emploi pour lequel il est d'usage constant de ne pas recourir au contrat de travail à durée indéterminée. Dans ce dernier cas, le secteur d'activité doit être défini par décret ou par une convention ou un accord collectif étendu, et cet usage doit tenir à la nature de l'activité exercée et au caractère par nature temporaire de l'emploi", "Pour réaliser une mission saisonnière ou temporaire répondant aux critères du 3° de l'article L. 1251-6",'Conserve les durées et objets possibles d’une mission, sans laisser son terme devenir celui du contrat unique.',extra=N+"les références du présent article au contrat de mission visent la lettre de mission. Le terme prévu ou la fin de son objet met fin à l'affectation auprès de l'utilisateur, sans mettre fin à l'emploi auprès de l'entreprise de travail temporaire. Les garanties des périodes d'intermission restent dues.")
transition('L1251-37-1',"aucun délai de carence légal n'est imposé entre deux lettres de mission d'un salarié en contrat unique. Cette dispense ne permet pas d'affecter un salarié à des tâches interdites, de contourner la sécurité, l'égalité de traitement ou les conditions licites de recours à la mise à disposition.",'Supprime la carence entre affectations du nouveau contrat sans supprimer ses anciennes exceptions favorables.',removed=["Suppression du délai de carence légal entre lettres de mission pour les salariés employés par contrat unique."])
transition('L1251-32',"l'achèvement d'une mission ne termine pas l'emploi à durée indéterminée et n'ouvre pas, à lui seul, l'indemnité de fin de mission. La rémunération garantie des intermissions reste due dans les conditions de l'article L. 1251-58-3. L'indemnité ordinaire éventuelle n'est due qu'à la rupture de l'emploi par l'employeur, dans les conditions de l'article L. 1234-9.",'Distingue fin d’affectation et rupture de l’emploi ; conserve le complément de 10 % des anciens contrats de mission.')
put('L1251-58-1',paragraphs("Pour tout salarié recruté à compter de l'entrée en vigueur de la réforme du contrat unique, l'entreprise de travail temporaire conclut un contrat unique à durée indéterminée pour l'exécution d'une ou de plusieurs missions successives. Chaque mission donne lieu :\n\n1° À un contrat de mise à disposition entre l'entreprise de travail temporaire et le client utilisateur, appelé entreprise utilisatrice ;\n\n2° À une lettre de mission établie par l'entreprise de travail temporaire.\n\nLa fin d'une mission ne rompt pas le contrat unique et n'interrompt pas l'ancienneté. Les contrats à durée indéterminée intérimaires déjà conclus conservent leurs garanties et leur ancienneté."),'Généralise aux nouveaux intérimaires l’architecture existante du CDI intérimaire, sans remise à zéro des emplois déjà indéterminés.')
replace('L1251-58-2',"Les dispositions du code du travail relatives au contrat à durée indéterminée s'appliquent au contrat mentionné à l'article L. 1251-58-1, sous réserve des dispositions de la présente section.","Les dispositions relatives au contrat unique s'appliquent aux nouveaux contrats mentionnés à l'article L. 1251-58-1, sous réserve des garanties de la présente section. Les contrats à durée indéterminée antérieurs conservent leurs droits acquis.",'Coordonne le régime unique en conservant intégralement les huit mentions écrites et l’assimilation des intermissions pour congés et ancienneté.')
put('L1251-58-3',base('L1251-58-3')+paragraphs("Cette rémunération mensuelle minimale reste garantie pendant les périodes sans mission prévues au contrat unique. Le remplacement des contrats de mission par des lettres de mission ne réduit pas cette garantie et ne remet pas en cause les droits plus favorables déjà acquis."),'Préserve expressément la garantie mensuelle existante lors de la généralisation du contrat unique ; ne supprime pas le salaire d’intermission.')
put('L1251-58-4',base('L1251-58-4')+paragraphs("Pour les nouveaux contrats uniques, aucune des règles relatives à la durée, au renouvellement ou à l'expiration d'une mission ne peut limiter la durée de l'emploi ou le rompre automatiquement. La rupture du contrat de travail relève du régime commun du contrat unique ; la protection de la santé, l'égalité de traitement et les recours propres à la mission restent applicables."),'Rend la passerelle entre règles de mission et CDI intérimaire opératoire sans rétablir un contrat de travail à terme.')
put('L1251-58-5',base('L1251-58-5')+paragraphs("Pour le contrat unique, ces substitutions portent exclusivement sur la mission et son document d'affectation. Elles ne transforment pas la lettre de mission en contrat de travail distinct, n'autorisent pas un nouveau CDD et ne subordonnent pas la poursuite de l'emploi à un renouvellement de mission."),'Conserve tous les renvois existants mais limite leur effet à l’affectation temporaire.')
put('L1251-58-6',base('L1251-58-6')+paragraphs("Cette dispense bénéficie également aux missions effectuées dans le cadre du contrat unique. Leur fin ou leur non-renouvellement est sans effet automatique sur la durée du contrat de travail ; les garanties de rémunération entre deux missions restent applicables."),'Étend la dispense favorable de durée totale aux missions dans le contrat unique sans réduire les garanties des intermissions.')
replace('L1251-60',"Besoin occasionnel ou saisonnier au sens du 3° de l'article L. 1242-2.","Besoin occasionnel ou saisonnier répondant aux critères du 3° de l'article L. 1251-6.",'Conserve les cas publics et plafonds 18/9/24/12 mois de mission sans fixer de terme à l’emploi privé de l’intérimaire.',extra="Lorsque le salarié est recruté par l'entreprise de travail temporaire sous contrat unique, les durées et le renouvellement prévus au présent article concernent la lettre de mission et la mise à disposition auprès de la personne publique. Ils ne mettent pas fin au contrat de travail avec l'entreprise de travail temporaire. Le statut propre des agents publics n'est pas modifié par cette coordination.",notes="Les renvois anciens aux lois statutaires de 1984 et 1986 sont conservés comme dans la source ; leur recodification vers le code général de la fonction publique reste un travail distinct, non déclaré accompli.")
# Portage : conserver le caractère autonome du financement des prestations.
put('L1254-7',paragraphs("Pour les recrutements effectués à compter de l'entrée en vigueur de la réforme du contrat unique, l'entreprise de portage salarial et le salarié porté concluent un contrat unique à durée indéterminée. Un contrat commercial de prestation peut avoir une durée limitée sans fixer de terme au contrat de travail.\n\n"+T),'Supprime la nouvelle embauche à terme en portage, en distinguant durée du service et durée de l’emploi.')
put('L1254-8',base('L1254-8')+paragraphs("Le principe de maintien du contrat de travail s'applique aussi à l'expiration ou au non-renouvellement de la prestation. Pour les contrats uniques, les règles de rémunération de l'article L. 1254-21 restent applicables ; le présent article ne crée pas une garantie générale de rémunération des périodes sans prestation. Une rupture de l'emploi exige une décision distincte soumise au régime du contrat unique."),'Empêche la fin automatique de l’emploi en fin de prestation sans inventer de salaire d’intermission propre au portage.')
transition('L1254-18',"aucun contrat de travail à durée déterminée de portage salarial ne peut être conclu ou renouvelé. Le régime du contrat unique s'applique, sans que les anciennes exceptions renvoyant aux articles L. 1242-10, L. 1242-16, L. 1243-1 à L. 1243-6 et L. 1243-8 puissent rétablir un terme à l'emploi.",'Ferme la passerelle CDD de portage pour les nouveaux emplois et conserve tous les anciens droits.')
put('L1254-20',paragraphs("Le contrat de travail est établi par écrit. Pour les recrutements effectués à compter de l'entrée en vigueur de la réforme, il porte la mention : « contrat unique à durée indéterminée en portage salarial ». Les contrats de portage à durée indéterminée antérieurs conservent leur validité et leurs garanties sans nouvelle formalité."),'Adapte la mention écrite au contrat unique sans imposer une réédition des anciens contrats.')
# Formation : durée pédagogique et avantages distincts de la durée de l'emploi.
put('L6222-7',paragraphs("Le contrat d'apprentissage conclu à compter de l'entrée en vigueur de la réforme est un contrat unique à durée indéterminée. Il débute par une période d'apprentissage régie par le présent titre. La durée de cette période ne limite pas celle de l'emploi.\n\nÀ l'issue de la période d'apprentissage, la relation se poursuit selon les titres II et III du livre II de la première partie. Aucun nouvel essai ne peut être imposé à raison de cette poursuite. L'ancienneté court depuis le début du contrat.\n\n"+T),'Généralise l’apprentissage à durée indéterminée, conserve la phase pédagogique et interdit un nouvel essai à son issue.')
body=base('L6222-7-1');old="La durée du contrat d'apprentissage, lorsqu'il est conclu pour une durée limitée, ou de la période d'apprentissage, lorsque le contrat d'apprentissage est conclu pour une durée indéterminée, varie entre six mois et trois ans";assert old in body;body=body.replace(old,"La période d'apprentissage du contrat unique varie entre six mois et trois ans").replace("la durée du contrat ou de la période d'apprentissage","la durée de la période d'apprentissage")
put('L6222-7-1',body+paragraphs("Les bornes et adaptations pédagogiques du présent article ne mettent pas fin au contrat unique. Pour les anciens contrats d'apprentissage à durée limitée, les règles antérieures de durée et de prolongation restent applicables sans création d'un nouveau contrat à terme après l'entrée en vigueur de la réforme."),'Conserve 6 mois/3 ans, cycle et toutes les adaptations liées aux compétences et engagements ; retire le terme d’emploi des nouveaux contrats.')
transition('L6222-18',"la rupture de l'emploi d'un apprenti relève du régime du contrat unique : préavis individuel de quinze jours calendaires à l'initiative de l'une ou l'autre partie, y compris pendant un essai expressément stipulé dans les limites du régime commun ; indemnité ordinaire de l'article L. 1234-9 uniquement si ses conditions sont réunies. L'arrivée au terme de la période d'apprentissage ne rompt pas l'emploi. La rupture patronale reste motivée, soumise à la procédure applicable, aux protections de santé et de représentation et au recours au juge. La faute grave, la force majeure et l'inaptitude restent soumises à leurs règles propres, sans exonération implicite des réparations d'une rupture illicite. L'apprenti peut solliciter le médiateur de l'article L. 6222-39 ; la médiation ne prolonge pas le préavis du salarié. Pour un apprenti mineur, l'acte de rupture à son initiative est signé avec son représentant légal ; en l'absence de réponse de celui-ci, le médiateur intervient dans un délai maximal de quinze jours calendaires après sa saisine pour rechercher son accord. Une copie de l'acte est adressée pour information au centre de formation. En liquidation, la rupture est notifiée par le liquidateur selon le régime du contrat unique, sans indemnité automatique correspondant à une formation restant à courir.",'Remplace pour les nouvelles embauches le régime de rupture pédagogique de 45 jours puis motifs limités par les règles du contrat unique, sans supprimer représentation du mineur ni recours.',removed=["Suppression, pour les nouveaux contrats, de la rupture libre spéciale pendant quarante-cinq jours de présence pratique puis du régime limitatif de rupture attaché à un emploi à terme.","Suppression de la médiation préalable obligatoire à la démission du nouvel apprenti majeur ; médiation accessible et protection du mineur conservées."])
replace('L6222-5-1',"pour l'exercice d'activités saisonnières au sens du 3° de l'article L. 1242-2", "pour l'exercice d'activités saisonnières dont les tâches se répètent chaque année selon une périodicité à peu près fixe en fonction des saisons ou des modes de vie collectifs",'Conserve l’apprentissage conjoint et ses deux qualifications sans terme d’emploi ; la phase pédagogique peut demeurer saisonnière.',extra="Pour un contrat unique nouveau, la convention tripartite répartit les périodes pédagogiques et l'exécution du travail sans fixer de terme à l'emploi. Le renvoi à l'article L. 6222-18 s'entend de son régime de rupture applicable à ce contrat. La fin d'une période chez l'un des employeurs ne rompt pas automatiquement le contrat ni ne remet l'ancienneté à zéro.")
transition('L6222-18-1',"l'exclusion définitive du centre de formation ne rompt pas automatiquement le contrat de travail. L'employeur peut engager une procédure de licenciement pour motif personnel si cette exclusion fait effectivement obstacle à l'exécution de la formation prévue et fournit un motif valable ; ce motif reste contrôlable par le juge. Le centre ou l'apprenti peut saisir le médiateur de l'article L. 6222-39. À défaut d'inscription dans un nouveau centre dans les deux mois suivant l'exclusion, la période d'apprentissage peut prendre fin par avenant ; le contrat unique se poursuit sans nouvelle embauche ni nouvel essai. Toute rupture de l'emploi est distincte et relève de l'article L. 6222-18.",'Supprime l’exigence de refaire un contrat après exclusion tout en conservant accès à la médiation et recherche d’un nouveau centre pendant deux mois.')
put('L6325-5',paragraphs("Le contrat de professionnalisation conclu à compter de l'entrée en vigueur de la réforme est un contrat unique à durée indéterminée, établi par écrit. L'action de professionnalisation peut avoir une durée limitée, sans fixer de terme à l'emploi.\n\nLe contrat est transmis à l'autorité administrative par le dépôt nécessaire à sa prise en charge ; aucune autorisation préalable de l'emploi n'est créée.\n\n"+T),'Remplace le CDD de professionnalisation par le contrat unique ; garde le dépôt utile à la prise en charge.')
put('L6325-6',paragraphs("Le salarié en contrat de professionnalisation bénéficie de l'ensemble des dispositions applicables aux autres salariés de l'entreprise dans la mesure où elles sont compatibles avec les exigences de sa formation.\n\nPour les nouveaux contrats uniques, une durée limitée de l'action de professionnalisation ne réduit pas l'ancienneté, ne termine pas l'emploi et ne prive pas le salarié des protections et recours du contrat unique."),'Conserve l’égalité de droits pendant la formation et empêche de confondre son terme avec celui de l’emploi.')
for n,old,new in [('L6325-8',"pendant la durée du contrat à durée déterminée ou de l'action de professionnalisation du contrat à durée indéterminée","pendant la durée de l'action de professionnalisation du contrat unique"),('L6325-9',"pendant la durée du contrat à durée déterminée ou de l'action de professionnalisation du contrat à durée indéterminée","pendant la durée de l'action de professionnalisation du contrat unique"),('L6325-11',"L'action de professionnalisation d'un contrat de professionnalisation à durée déterminée ou qui se situe au début d'un contrat de professionnalisation à durée indéterminée","L'action de professionnalisation située au début du contrat unique"),('L6325-13',"Dans le cadre du contrat de professionnalisation à durée déterminée ou d'actions de professionnalisation engagées dans le cadre de contrats à durée indéterminée","Dans le cadre des actions de professionnalisation engagées au début d'un contrat unique")]:
 body=base(n);assert old in body,(n,old);body=body.replace(old,new)
 if n=='L6325-13':body=body.replace("de la durée totale du contrat","de la durée totale de l'action de professionnalisation")
 put(n,body+paragraphs("Ces règles s'appliquent aux phases de professionnalisation des nouveaux contrats uniques, sans fixer de terme à l'emploi. Les anciens contrats et leurs rémunérations, durées de formation et garanties demeurent régis par les règles qui leur étaient applicables."),'Conserve les minima de salaire et de formation propres à cet article, en les rattachant à la phase pédagogique plutôt qu’à un CDD.')
put('L6325-15',paragraphs("Est nulle toute clause imposant au salarié en contrat de professionnalisation le remboursement des dépenses de formation à l'employeur du fait de la rupture du contrat de travail.\n\nCette interdiction s'applique aussi au contrat unique et à une rupture à l'initiative du salarié ; la fin de la phase pédagogique ne peut justifier une telle dette."),'Préserve et explicite la dispense favorable de remboursement lors du passage au contrat unique.')
body=base('L6325-4-1').replace("activités saisonnières au sens du 3° de l'article L. 1242-2","activités saisonnières dont les tâches se répètent chaque année selon une périodicité à peu près fixe en fonction du rythme des saisons ou des modes de vie collectifs").replace("un contrat de professionnalisation à durée déterminée","un contrat unique à durée indéterminée comportant une action de professionnalisation")
old="La période d'essai prévue à l'article L. 1242-10 est applicable au début de la première période de travail effectif chez chacun des employeurs.";assert old in body;body=body.replace(old,"Un essai ne peut être stipulé qu'au début du contrat unique, selon ses règles communes ; le changement d'affectation entre employeurs ne crée pas un nouvel essai.")
old="Ce contrat peut être rompu, dans les conditions applicables aux contrats à durée déterminée, à l'initiative de chacune des parties, laquelle prend en charge les conséquences financières éventuelles de cette rupture.";assert old in body;body=body.replace(old,"La rupture de l'emploi relève des règles du contrat unique. La convention tripartite répartit les obligations entre employeurs ; elle ne peut réduire les droits du salarié ni fixer de terme à l'emploi.")
put('L6325-4-1',body+paragraphs(T),'Conserve le contrat conjoint saisonnier et les deux qualifications ; retire le CDD et le double essai successif.',removed=["Suppression de l'emploi à durée déterminée et de la possibilité d'un nouvel essai chez chacun des deux employeurs du contrat conjoint."])
put('L6325-23',paragraphs("Une entreprise de travail temporaire peut conclure un contrat unique à durée indéterminée comportant une action de professionnalisation. Les activités professionnelles en relation avec les enseignements reçus sont exercées au cours des missions régies par le chapitre Ier du titre V du livre II de la première partie.\n\nLa durée pédagogique de l'action et celle des missions ne limitent pas la durée de l'emploi. Les garanties des intermissions restent applicables.\n\n"+T),'Conserve l’accès à la professionnalisation en intérim en supprimant son CDD spécifique.')
replace('L6323-11',"Les salariés à caractère saisonnier, au sens du 3° de l'article L. 1242-2", "Les salariés dont les tâches sont appelées à se répéter chaque année selon une périodicité à peu près fixe en fonction des saisons ou des modes de vie collectifs, y compris dans un contrat unique",'Conserve les abondements saisonniers futurs du CPF sans renvoi à un CDD abrogé ; toutes les autres règles CPF sont maintenues.')
put('L6331-6',paragraphs("La contribution dédiée au financement du compte personnel de formation assise sur les rémunérations des salariés en contrat à durée déterminée est supprimée pour les rémunérations correspondant aux périodes de travail effectuées à compter de l'entrée en vigueur de la réforme du contrat unique, y compris lorsqu'un ancien CDD se poursuit. Aucun prélèvement de remplacement n'est institué sur les contrats uniques.\n\nPour les périodes de travail antérieures, la contribution de 1 % reste établie et recouvrée selon les règles qui leur étaient applicables. Les exclusions des contrats ayant pour objet principal l'accès ou le maintien dans l'emploi par la formation professionnelle ou l'alternance et des emplois saisonniers demeurent applicables à ces périodes. Les créances de restitution et droits déjà ouverts sont conservés.\n\nLa suppression de cette recette ne supprime ni les droits CPF acquis, ni leur portabilité, ni les abondements favorables attachés aux situations éligibles."),'Supprime effectivement la contribution CPF-CDD de 1 % pour les rémunérations futures, sans l’étendre au contrat unique ni supprimer ses anciennes exclusions.',removed=["Suppression de la contribution de 1 % CPF-CDD sur toutes les rémunérations correspondant à des périodes de travail postérieures à l'entrée en vigueur de la réforme."])
put('L6321-9',paragraphs("Sans préjudice de la section 2, lorsqu'un employeur s'engage, par convention ou accord collectif étendu ou par contrat de travail, à employer pour la saison suivante un salarié dont les tâches se répètent chaque année selon une périodicité à peu près fixe en fonction des saisons ou des modes de vie collectifs, une action du plan de développement des compétences peut être organisée avant cette saison. Pour les relations nouvelles, l'emploi relève du contrat unique ; la formation constitue une phase de ce contrat et sa fin ne termine pas l'emploi.\n\nLa rémunération de cette phase ne peut être inférieure à celle qu'un salarié de qualification équivalente, occupant les mêmes fonctions, percevrait dans la même entreprise ; les fonctions retenues sont celles prévues pour la saison suivante.\n\nLes salariés concernés peuvent aussi bénéficier d'un abondement du compte personnel de formation par accord de branche ou d'entreprise. Cet avantage reste ouvert aux contrats uniques futurs.\n\n"+T),'Remplace le CDD de formation intersaison par une phase rémunérée du contrat unique ; conserve égalité de salaire et abondement CPF.')
replace('L6324-3',"Cette période de reconversion dans une autre entreprise prend la forme d'un contrat à durée indéterminée mentionné au premier alinéa de l'article L. 1221-2 ou d'un contrat à durée déterminée d'au moins six mois mentionné au 5° de l'article L. 1242-3, qui précise les modalités d'organisation de la période de reconversion et prévoit une période d'essai dans les conditions prévues à la section 4 du chapitre Ier du titre II du livre II de la première partie et aux articles L. 1242-10 et L. 1242-11.","Pour les nouvelles embauches, cette reconversion dans une autre entreprise se déroule dans le cadre d'un contrat unique à durée indéterminée. Un accord écrit précise la durée et l'organisation de la phase de reconversion sans limiter la durée de l'emploi. Un essai peut être expressément stipulé dans les limites du régime commun du contrat unique ; il n'est pas obligatoire. Les accords déterminent les conditions du retour anticipé si l'accueil cesse sans rupture régulière du contrat d'origine.",'Supprime l’alternative CDD de reconversion et l’essai obligatoire, en conservant le contrat d’origine et les modalités de retour.',extra=T,notes="Les notes officielles d'entrée en vigueur au 1er janvier 2026 et le maintien des actions engagées avant cette date sont conservés dans la source et ne valent pas date de promulgation du projet.")
body=base('L6324-7');old="ou, lorsque le contrat de travail est à durée déterminée, d'un commun accord en application de l'article L. 1243-1";assert body.count(old)==2;body=body.replace(old,"ou, pour un ancien CDD encore en cours, d'un commun accord dans le respect de ses règles antérieures")
put('L6324-7',body+paragraphs("Si aucun essai n'a été stipulé dans le nouveau contrat d'accueil, l'accord écrit de reconversion fixe la date d'appréciation de sa poursuite et les modalités de retour, sans terme automatique de l'emploi. Le refus de poursuivre la reconversion ou de réintégrer le poste d'origine ne vaut pas consentement anticipé à une rupture conventionnelle : le consentement libre et les garanties de l'article L. 1237-11 restent requis. La période pédagogique peut finir sans rompre l'un ou l'autre emploi."),'Conserve droit au retour et rupture conventionnelle consentie, réserve le renvoi CDD aux anciens contrats et couvre l’absence d’essai désormais facultatif.')
replace('L6332-14',"dans les cas de rupture du contrat définis aux articles L. 1233-3, L. 1243-4 et L. 6222-18", "dans les cas de rupture du contrat définis aux articles L. 1233-3 et L. 6222-18, en cas de rupture du contrat unique par l'employeur avant la fin de l'action de formation, ainsi que dans les cas relevant de l'ancien article L. 1243-4 pour les contrats antérieurs",'Préserve les prises en charge après rupture et les étend aux situations homologues du contrat unique ; tous les financements, plafonds et publics demeurent entiers.',extra="Les durées de prise en charge d'une action d'apprentissage ou de professionnalisation ne fixent pas de terme au contrat unique. Le changement de forme de l'emploi ne ferme pas les prises en charge favorables aux futurs bénéficiaires éligibles.")
# POE : conserver tous les publics et financeurs, sans nouveau contrat à terme.
put('L6326-1',paragraphs("La préparation opérationnelle à l'emploi individuelle permet à un demandeur d'emploi, à un travailleur handicapé employé dans une entreprise adaptée mentionnée à l'article L. 5213-13, à un salarié en contrat aidé conclu en application de l'article L. 5134-19-1 ou à un salarié en insertion auprès d'un employeur relevant de l'article L. 5132-4 de recevoir la formation nécessaire pour occuper un emploi correspondant à une offre déposée auprès de France Travail. Ces publics comprennent les nouveaux salariés en contrat unique et les titulaires des contrats aidés ou d'insertion antérieurs, sans perte d'éligibilité du fait de la suppression des nouveaux CDD.\n\nL'offre est située dans la zone géographique privilégiée définie par le contrat d'engagement du demandeur d'emploi. La formation est dispensée avant l'entrée dans l'entreprise.\n\nUn décret précise les modalités d'emploi et les phases pédagogiques ou missions pouvant suivre la formation. Pour toute embauche nouvelle, le contrat est unique et à durée indéterminée ; la durée prévue d'une formation, aide ou mission n'en limite pas la durée."),'Maintient l’accès de tous les publics POEI et ferme le renvoi réglementaire à de nouveaux CDD.')
put('L6326-3',paragraphs("La préparation opérationnelle à l'emploi collective permet à plusieurs demandeurs d'emploi, ainsi qu'aux salariés en contrat aidé conclu en application de l'article L. 5134-19-1 ou en insertion auprès d'un employeur relevant de l'article L. 5132-4, de bénéficier de la formation nécessaire pour occuper des emplois répondant aux besoins identifiés par un accord de branche ou, à défaut, par le conseil d'administration d'un opérateur de compétences. Ces publics comprennent les salariés en contrat unique et les titulaires des anciens contrats aidés ou d'insertion encore en cours.\n\nL'embauche qui suit cette préparation prend la forme du contrat unique à durée indéterminée. Elle peut comporter une action de professionnalisation d'au moins douze mois ou une période d'apprentissage ; ces durées pédagogiques ne fixent pas le terme de l'emploi. L'accès à une embauche directe sans action de professionnalisation demeure ouvert.\n\nLa formation est financée par l'opérateur de compétences compétent. L'État et France Travail peuvent également la financer dans les conditions prévues, le cas échéant, par convention avec cet opérateur.\n\nPour les demandeurs d'emploi de moins de vingt-six ans, la formation peut être dispensée dans un centre de formation d'apprentis.\n\nLes conventions et prises en charge antérieures restent valables ; aucune aide n'est retirée au seul motif du remplacement d'une embauche à durée déterminée par un contrat unique."),'Conserve POEC, publics, cofinancements et accès CFA ; remplace la liste des embauches à terme par des phases dans l’emploi indéterminé.')
put('L6326-4',paragraphs("Pendant la préparation opérationnelle à l'emploi, l'employeur maintient la rémunération du salarié en contrat aidé conclu en application de l'article L. 5134-19-1 ou en insertion auprès d'un employeur relevant de l'article L. 5132-4. Cette garantie bénéficie aussi aux nouveaux contrats uniques de même objet et aux anciens contrats encore en cours.\n\nL'opérateur de compétences compétent, l'État ou France Travail peuvent prendre en charge cette rémunération, après déduction des aides financières et exonérations de cotisations sociales dont l'employeur bénéficie pour le même emploi. Ces aides et exonérations restent ouvertes aux situations éligibles dans le contrat unique."),'Maintient rémunération et prise en charge POE dans le nouvel emploi sans fermer les exonérations aux bénéficiaires futurs.')
put('D6326-1',paragraphs("À l'issue de la préparation opérationnelle à l'emploi individuelle de l'article L. 6326-1, toute embauche nouvelle prend la forme d'un contrat unique à durée indéterminée, directement auprès de l'employeur ou auprès d'une entreprise de travail temporaire.\n\nLes modalités suivantes restent ouvertes sans limiter la durée de l'emploi :\n\n1° Une embauche directe ou un contrat unique intérimaire régi par l'article L. 1251-58-1 ;\n\n2° Une action de professionnalisation d'au moins six mois ;\n\n3° Une période d'apprentissage d'au moins six mois ;\n\n4° Une affectation initiale identifiée d'au moins six mois ;\n\n5° Une affectation saisonnière répondant aux critères du 3° de l'article L. 1251-6 et prévue pour au moins quatre mois ;\n\n6° Une ou plusieurs missions auprès d'utilisateurs, prévues pour une durée totale d'au moins six mois dans les neuf mois suivant la formation, dans le cadre d'un même contrat unique intérimaire.\n\nLes durées des 2° à 6° sont des conditions d'organisation ou de prise en charge de la préparation, sans terme automatique du contrat de travail et sans indemnité de rupture supplémentaire créée au présent article. Les conventions de prise en charge antérieures restent valables et leurs avantages ne sont pas retirés du seul fait du passage au contrat unique."),'Conserve les six voies de POEI et leurs durées favorables en séparant engagement d’affectation et durée indéterminée de l’emploi.')
# Préavis professionnels : quinze jours dans le nouveau régime, anciens droits maintenus.
transition('L5213-9',"le préavis individuel est de quinze jours calendaires, conformément à l'article L. 1234-1, sans doublement automatique de sa durée au titre du présent article. Cette règle ne supprime ni les aménagements du poste et du travail, ni l'interdiction de discrimination, ni les mesures de reclassement et de maintien dans l'emploi applicables aux bénéficiaires du chapitre II.",'Coordonne explicitement le préavis du nouveau contrat unique avec le régime du handicap ; conserve le doublement des contrats antérieurs.',removed=["Suppression du doublement légal du préavis pour les nouveaux contrats uniques, afin d'appliquer le délai individuel de quinze jours confirmé par l'auteur."],notes="Choix de réforme explicite retirant une durée protectrice pour les nouvelles embauches ; égalité de traitement, aménagement raisonnable et compatibilité internationale à contrôler. Les anciens contrats conservent le doublement/plafond de trois mois.")
transition('L7112-2',"le préavis individuel d'un journaliste professionnel est de quinze jours calendaires, à l'initiative de l'une ou l'autre partie. La dispense favorable du 3° de l'article L. 7112-5 demeure applicable. Les autorisations et protections particulières restent distinctes de la durée de ce préavis.",'Remplace les préavis sectoriels d’un ou deux mois par quinze jours dans le nouveau contrat ; conserve la clause de conscience et les préavis antérieurs.',removed=["Suppression des minima sectoriels d'un et deux mois de préavis pour les nouveaux contrats uniques de journalistes."])
transition('L7313-9',"le préavis individuel du voyageur, représentant ou placier est de quinze jours calendaires à l'initiative de l'une ou l'autre partie. Les indemnités de clientèle et commissions acquises relèvent de leurs règles propres et ne sont pas absorbées par l'indemnité ordinaire de rupture.",'Coordonne les trois anciens minima VRP avec quinze jours sans supprimer les commissions ni les indemnités de clientèle.',removed=["Suppression des préavis légaux d'un, deux ou trois mois pour les nouvelles embauches de VRP en contrat unique."])
# Effectifs : éviter de compter deux fois l'emploi remplacé après conversion du CDD.
body=base('L1111-2');old="Toutefois, les salariés titulaires d’un contrat de travail à durée déterminée et les salariés mis à disposition par une entreprise extérieure, y compris les salariés temporaires, sont exclus du décompte lorsqu’ils remplacent un salarié absent ou dont le contrat de travail est suspendu, notamment en raison d’un congé de maternité, d’un congé d’adoption ou d’un congé parental d’éducation";assert old in body
body=body.replace(old,"Toutefois, les salariés recrutés pour remplacer un salarié absent ou dont le contrat est suspendu, y compris sous contrat unique, ainsi que les salariés mis à disposition pour ce remplacement, sont exclus du décompte pendant la seule durée du remplacement, notamment lors d'un congé de maternité, d'adoption ou d'éducation parentale. Le salarié qui reste employé après la fin du remplacement est ensuite décompté selon la règle applicable à son emploi")
put('L1111-2',body+paragraphs("Pour les nouveaux contrats uniques à temps plein, le 1° s'applique, sous réserve de l'exclusion temporaire de remplacement prévue au 2°. Le 3° continue de s'appliquer aux emplois à temps partiel. Les salariés intérimaires restent soumis aux règles de mise à disposition du 2° ; leur emploi à durée indéterminée ne les compte pas une seconde fois chez l'utilisateur au titre du 1°. Les anciens CDD conservent leurs règles de proratisation."),'Conserve toutes les règles de calcul et étend la dispense de remplacement au contrat unique pour éviter un effet de seuil artificiel.')
# Journalistes : indemnité ordinaire commune ; conscience/cession reste une réparation spéciale.
transition('L7112-3',"l'indemnité ordinaire due lorsque l'employeur rompt l'emploi d'un journaliste relève de l'article L. 1234-9. L'indemnité particulière liée à une rupture par le journaliste dans les circonstances de l'article L. 7112-5 reste distincte et ne constitue pas une indemnité de démission ordinaire.",'Applique le barème ordinaire unique aux nouveaux journalistes ; conserve le barème antérieur et les droits spéciaux de conscience/cession.',removed=["Remplacement du minimum ordinaire sectoriel d'un mois par année avec maximum de quinze mois pour les nouvelles embauches par le barème commun du contrat unique."])
put('L7112-4',base('L7112-4')+paragraphs("Pour les nouveaux contrats uniques, la commission reste compétente pour l'indemnité spéciale due dans les circonstances de l'article L. 7112-5 lorsque l'ancienneté excède quinze années, ainsi que pour toute composante antérieure qui relève encore de cette compétence. L'indemnité ordinaire du nouvel emploi suit l'article L. 1234-9 et ses voies de recours ; elle n'est pas augmentée au seul motif du franchissement de quinze ans. La répartition entre droits anciens et nouveaux ne peut supprimer une créance acquise ni indemniser deux fois une même période."),'Conserve la commission et toutes ses modalités pour les droits encore spéciaux, sans recréer un barème ordinaire dérogatoire dans le contrat unique.')
put('L7112-5',base('L7112-5')+paragraphs("Ces circonstances demeurent des cas spéciaux distincts de la démission ordinaire du contrat unique. Pour le nouveau contrat, elles ouvrent une indemnité spéciale au moins égale à un mois des derniers appointements par année ou fraction d'année de collaboration, dans la limite de quinze mensualités ; au-delà de quinze ans d'ancienneté, l'article L. 7112-4 s'applique. La dispense de préavis du 3° reste ouverte. L'absence d'indemnité ordinaire pendant la première année ou en cas de démission ne supprime pas cette protection spécifique. Une même période ne donne pas lieu deux fois à une indemnité de même objet."),'Préserve les droits favorables de conscience, cession et cessation, en explicitant qu’ils sont spéciaux et ne recréent pas une indemnité générale de démission.')
assert set(out)==set(by),(set(by)-set(out),set(out)-set(by))
rows=[out[a['number']] for a in sources];(ROOT/'answer.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
sys.path.insert(0,str(Path('legal-rewrite').resolve()));from run_exhaustive import validate_answer,mentions_possible_relief
for a in sources:a['benefit_check_required']=mentions_possible_relief(a['source_xml'])
validate_answer(rows,sources)
print(json.dumps({'articles':len(rows),'whole_source_characters':sum(len(a['source_xml'])+len(a['source_notes_xml']) for a in sources),'validated':True}))
